const LEAGUE_HONORS=[['champion','Champion'],['runnerUp','Runner-up'],['finalsMvp','Finals MVP'],['mvp','MVP'],['dpoy','Defensive Player of the Year'],['roy','Rookie of the Year'],['mip','Most Improved Player'],['sixth','Sixth Player of the Year'],['coach','Coach of the Year']];
function seasonHonors(){
 if(state.champion===null)return null;
 const rows=awardRaceRows(),select=(list,key)=>[...list].filter(r=>Number.isFinite(r[key])).sort((a,b)=>b[key]-a[key]||a.id-b.id)[0],person=r=>r?{name:r.name,team:state.teams[r.club]?.city+' '+state.teams[r.club]?.name,...(Number.isInteger(r.id)?{id:r.id}:{})}:null;
 const clubName=id=>{const t=state.teams[id];return t?{name:t.city+' '+t.name,team:''}:null},final=state.history.find(g=>g.stage==='Championship'&&g.winner===state.champion),runner=final?(final.a===state.champion?final.b:final.a):null;
 const finalPlayers=final?.box.filter(p=>p.team===state.teams[state.champion].abbr&&p.played!==false&&p.mp>0).map(p=>({...p,club:state.champion,id:p.playerId??0,finalScore:p.pts+.7*p.reb+.7*p.ast+(p.stl||0)+(p.blk||0)-(p.tov||0)}))||[];
 const contribution=r=>[r.pts,r.reb,r.ast,r.stl,r.blk,r.tov].every(Number.isFinite)&&r.gp>0?(r.pts+.7*r.reb+.7*r.ast+r.stl+r.blk-r.tov)/r.gp:null;
 const improved=rows.filter(r=>!r.rookie).map(r=>{const prior=(state.statsArchive||[]).find(p=>p.year===state.year-1&&p.id===r.id&&p.gp>=10),old=prior?contribution(prior):null,current=contribution(r);return {...r,improvement:old!==null&&current!==null?current-old:null}}).filter(r=>r.improvement>0);
 const coaches=state.teams.filter(t=>!expansionPendingSeason(t)&&t.w+t.l>0).map(t=>({t,rate:t.w/(t.w+t.l)})).sort((a,b)=>b.rate-a.rate||b.t.w-a.t.w||a.t.id-b.t.id),top=coaches[0]?.t;
 return {year:state.year,champion:clubName(state.champion),runnerUp:clubName(runner),finalsMvp:person(select(finalPlayers,'finalScore')),mvp:person(select(rows,'score')),dpoy:person(select(rows,'defense')),roy:person(select(rows.filter(r=>r.rookie),'score')),mip:person(select(improved,'improvement')),sixth:person(select(rows.filter(r=>r.bench),'score')),coach:top?{name:coachFor(top).name,team:top.city+' '+top.name}:null};
}
function archiveLeagueHonors(){if(state.champion===null||state.leagueHistory?.some(r=>r.year===state.year))return;const row=seasonHonors();if(row)(state.leagueHistory??=[]).push(row)}
const honorsOwnerFinalizeBefore=ownerFinalize;ownerFinalize=function(){const result=honorsOwnerFinalizeBefore();archiveLeagueHonors();return result};
const honorsChampionArchiveBefore=archivePlayoffChampion;archivePlayoffChampion=function(){archiveLeagueHonors();return honorsChampionArchiveBefore()};
function leagueHistoryRows(){const rows=[...(state.leagueHistory||[])];if(state.champion!==null&&!rows.some(r=>r.year===state.year))rows.push(seasonHonors());for(const c of state.championsArchive||[])if(!rows.some(r=>r.year===c.year))rows.push({year:c.year,champion:{name:c.name,team:''}});return rows.sort((a,b)=>b.year-a.year)}
function leagueHistoryView(){const rows=leagueHistoryRows(),cell=value=>value?`<strong>${escapeHTML(value.name)}</strong>${value.team?`<small>${escapeHTML(value.team)}</small>`:''}`:'<span class="muted">Not recorded</span>';return `<section class="panel league-history"><div class="panelhead"><h2>League history</h2><span>${rows.length} recorded seasons</span></div><p class="note">Yearly champions and award winners. Regular-season awards are announced at the end of the regular season. Champions and Finals MVP follow the championship.</p><div class="scroll" tabindex="0" role="region" aria-label="Champions and annual awards"><table><thead><tr><th>Season</th>${LEAGUE_HONORS.map(([key,label])=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r.year}–${String(r.year+1).slice(-2)}</th>${LEAGUE_HONORS.map(([key])=>`<td>${cell(r[key])}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="10">No completed seasons yet. Finish the playoffs to record the first champion and award winners.</td></tr>'}</tbody></table></div><details class="note"><summary>Award selection rules</summary><p>MVP, Rookie and Sixth Player use the same cumulative game-score model as Award Races. Defensive Player uses steals, blocks and defensive rebounds. Candidates must play at least half the leading team’s regular-season games; Sixth Player requires more bench appearances than starts.</p><p>Most Improved compares weighted per-game production with the previous season (at least 10 prior games), excludes rookies and requires positive improvement. Finals MVP uses weighted box-score production from the champion’s players in the championship game. Coach of the Year goes to the team with the best regular-season win percentage, with wins as the first tiebreaker.</p><p>Missing historical results and awards without eligible candidates show “Not recorded.” Earlier seasons are never assigned invented winners.</p></details></section>`}
function readLeagueHistory(raw,bad){if(raw===undefined)return undefined;if(!Array.isArray(raw)||raw.length>8101||new Set(raw.map(r=>r.year)).size!==raw.length)bad('invalid league history');return raw.map(r=>{if(!r||!Number.isInteger(r.year)||r.year<1900||r.year>10000)bad('invalid league history season');const out={year:r.year};for(const [key] of LEAGUE_HONORS){const v=r[key];if(v!==null&&v!==undefined&&(!v||typeof v.name!=='string'||!v.name.trim()||v.name.length>150||typeof v.team!=='string'||v.team.length>100))bad('invalid league honor');if(v?.id!==undefined&&(!Number.isInteger(v.id)||v.id<0||v.id>10000000))bad('invalid league honor player ID');out[key]=v?{name:v.name,team:v.team,...(v.id!==undefined?{id:v.id}:{})}:null}return out})}
